import re
import sys

sys.setrecursionlimit(20000)
if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)


class _EvalError(Exception):
    pass


def calc(expr: str) -> int | str:
    tokens = re.findall(r"\d+|[+\-*/%^()]", expr)
    pos = 0
    n = len(tokens)

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while pos < n and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == "+":
                val += right
            else:
                val -= right
        return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while pos < n and tokens[pos] in ("*", "/", "%"):
            op = tokens[pos]
            pos += 1
            right = parse_unary()
            if op == "*":
                val *= right
            else:
                if right == 0:
                    raise _EvalError()
                q = -(abs(val) // abs(right)) if (val < 0) ^ (right < 0) else abs(val) // abs(right)
                if op == "/":
                    val = q
                else:
                    val = val - right * q
        return val

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while pos < n and tokens[pos] == "-":
            neg = not neg
            pos += 1
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        nonlocal pos
        base = parse_atom()
        if pos < n and tokens[pos] == "^":
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise _EvalError()
            return base ** exp
        return base

    def parse_atom() -> int:
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        if tok == "(":
            val = parse_expr()
            pos += 1  # consume ')'
            return val
        return int(tok)

    try:
        return parse_expr()
    except _EvalError:
        return "error"
